use std::fmt;

use crate::expression::{Expression, Literal};
use crate::statement::Statement;
use crate::token::{Keyword, Token, TokenLiteral, TokenType};

#[cfg(test)]
mod tests;

pub struct Parser {
    // The list of tokens generated by
    // the scanner.
    tokens: Vec<Token>,

    // The index of the current token
    // in the tokens vector.
    index: usize,
}

#[derive(Debug, PartialEq)]
pub struct ParserError {
    pub message: String,
    pub token: Token,
}

impl fmt::Display for ParserError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(
            f,
            "[line {}] Error: {} - Token: {}",
            self.token.line, self.message, self.token.lexeme
        )
    }
}

pub type ParserResult<T> = Result<T, ParserError>;

impl Parser {
    // Create a new Parser and ensure
    // the list of tokens includes at
    // least an Eof.
    pub fn new(mut tokens: Vec<Token>) -> Self {
        if tokens.last().is_none_or(|t| t.ttype != TokenType::Eof) {
            tokens.push(Token::eof());
        }

        Self { tokens, index: 0 }
    }

    // Return the current token.
    fn current_token(&self) -> &Token {
        &self.tokens[self.index]
    }

    // Skip the current token, unless
    // we already reached the end.
    // Return the previous token.
    fn consume(&mut self) -> &Token {
        let previous = self.index;

        if self.current_token().ttype != TokenType::Eof {
            self.index += 1;
        }

        &self.tokens[previous]
    }

    // Check if the type of the current token
    // corresponds to the given `TokenType` variant.
    // This is true only if the current token
    // is not `Eof` and if there is a match between
    // the current token and the given token type.
    fn check_current(&self, token_type: &TokenType) -> bool {
        let current_token = self.current_token();

        current_token.ttype != TokenType::Eof && current_token.ttype == *token_type
    }

    // Check if the current token is
    // the End of File.
    fn check_eof(&self) -> bool {
        self.current_token().ttype == TokenType::Eof
    }

    // Check if the type of the current token matches
    // one of the provided token types. If there is a
    // match, it consumes the token and returns it.
    fn match_current(&mut self, token_types: &[TokenType]) -> Option<&Token> {
        if token_types.iter().any(|ttype| self.check_current(ttype)) {
            Some(self.consume())
        } else {
            None
        }
    }

    // Consume the current token if it matches
    // the given type, otherwise return an
    // error with the given message.
    fn expect(&mut self, token_type: &TokenType, message: &str) -> ParserResult<&Token> {
        if !self.check_current(token_type) {
            return Err(ParserError {
                message: String::from(message),
                token: self.current_token().clone(),
            });
        }

        Ok(self.consume())
    }

    // Parse the next three tokens and try to
    // identify a binary operation that uses
    // one of the given operators.
    // Fall back to the provided next function
    // if the binary operation cannot be identified.
    //
    // binary -> next ( ( operators ) next )*
    fn binary(
        &mut self,
        operators: &[TokenType],
        next: fn(&mut Self) -> ParserResult<Expression>,
    ) -> ParserResult<Expression> {
        // Parse the left side of the binary operation.
        // This expression might be recursively
        // transformed if there is a chain of
        // binary operations.
        let mut expression = next(self)?;

        // Add the current operation to a
        // binary structure while the next token
        // matches one of the given operators.
        while let Some(t) = self.match_current(operators) {
            // Get the operator out of
            // self to allow further
            // mutable borrows.
            let operator = t.clone();

            // Parse the right side of
            // the binary operation.
            let right = next(self)?;

            // Transform the expression, adding
            // the previous one to the left side
            // recursively.
            expression = Expression::Binary {
                left: Box::new(expression),
                operator,
                right: Box::new(right),
            };
        }

        Ok(expression)
    }

    // The main entry point of the parser.
    pub fn parse(&mut self) -> ParserResult<Vec<Statement>> {
        // Create a vector to host
        // the parsed statements.
        let mut statements = Vec::<Statement>::new();

        // Parse and collect statements
        // until we reach the end of the file.
        while !self.check_eof() {
            statements.push(self.statement()?);
        }

        Ok(statements)
    }

    // Parse the next tokens as a statement.
    pub fn statement(&mut self) -> ParserResult<Statement> {
        // Try to parse the next tokens
        // as a print statement. If successful,
        // return the parsed statement.
        if let Some(s) = self.statement_print()? {
            return Ok(s);
        }

        // Try to parse the next tokens
        // as a var statement. If successful,
        // return the parsed statement.
        if let Some(s) = self.statement_var()? {
            return Ok(s);
        }

        // Try to parse the next tokens
        // as a block statement. If successful,
        // return the parsed statement.
        if let Some(s) = self.statement_block()? {
            return Ok(s);
        }

        // If we are here, the statement
        // contains only an expression.
        self.statement_expression()
    }

    // Parse the next tokens as a print statement.
    pub fn statement_print(&mut self) -> ParserResult<Option<Statement>> {
        // Check the presence of the keyword `print`.
        if self
            .match_current(&[TokenType::Reserved(Keyword::Print)])
            .is_none()
        {
            return Ok(None);
        }

        // Parse the expression contained
        // in the statement.
        let expression = self.expression()?;

        // Enforce the presence of a semicolon.
        // If not present, the statement
        // is invalid.
        self.expect(&TokenType::Semicolon, "Invalid statement")?;

        Ok(Some(Statement::Print(expression)))
    }

    // Parse the next tokens as a var statement.
    pub fn statement_var(&mut self) -> ParserResult<Option<Statement>> {
        // Check the presence of the keyword `var`.
        if self
            .match_current(&[TokenType::Reserved(Keyword::Var)])
            .is_none()
        {
            return Ok(None);
        }

        // Enforce the presence of an identifier.
        // If not present, the statement
        // is invalid.
        let identifier = self
            .expect(&TokenType::Identifier, "Invalid statement")?
            .clone();

        // If the next token is an equal `=`,
        // skip it and parse the remaining tokens
        // as an expression. Otherwise
        // just return `nil`.
        let expression = match self.match_current(&[TokenType::Equal]) {
            Some(_) => self.expression()?,
            None => Expression::Literal(Literal::Nil),
        };

        // Enforce the presence of a semicolon.
        // If not present, the statement
        // is invalid.
        self.expect(&TokenType::Semicolon, "Invalid statement")?;

        Ok(Some(Statement::Var(identifier.lexeme, expression)))
    }

    pub fn statement_block(&mut self) -> ParserResult<Option<Statement>> {
        // Check the presence of the
        // opening curly brace `{`.
        if self.match_current(&[TokenType::LBrace]).is_none() {
            return Ok(None);
        }

        // Prepare an empty vector to host
        // the statements contained in the block.
        let mut statements: Vec<Statement> = Vec::new();

        // Parse statements until we find the
        // closing curly brace `}` or the end
        // of the file.
        // Add each statement to the vector.
        while !self.check_current(&TokenType::RBrace) && !self.check_eof() {
            statements.push(self.statement()?);
        }

        // Enforce the presence of a
        // closing curly brace `}`.
        // If not present, the statement
        // is invalid.
        self.expect(&TokenType::RBrace, "Invalid statement")?;

        Ok(Some(Statement::Block(statements)))
    }

    // Parse the next tokens as an expression statement.
    pub fn statement_expression(&mut self) -> ParserResult<Statement> {
        // Parse the expression contained
        // in the statement.
        let expression = self.expression()?;

        // Enforce the presence of a semicolon.
        // If not present, the statement
        // is invalid.
        self.expect(&TokenType::Semicolon, "Invalid statement")?;

        Ok(Statement::Expression(expression))
    }

    // Parse the next tokens as an expression.
    pub fn expression(&mut self) -> ParserResult<Expression> {
        self.assignment()
    }

    // Parse the next three tokens and try to
    // identify an assignment.
    //
    // assignment -> IDENTIFIER "=" assignment | equality
    fn assignment(&mut self) -> ParserResult<Expression> {
        // Parse the left side of the assignment.
        let left = self.equality()?;

        // Match an equal `=`.
        // If not present the expression
        // is simply the left side that
        // we already parsed.
        let Some(t) = self.match_current(&[TokenType::Equal]) else {
            return Ok(left);
        };

        // If we reach this point we found
        // an equal `=` in the expression.
        // The token is cloned for later use.
        // We cannot use the token itself
        // later as it comes from a mutable
        // borrow of self (self.match_current)
        // and we need another mutable borrow
        // later (self.assignment).
        let equal = t.clone();

        // Parse the right side of the assignment.
        // This can be another assignment.
        let right = self.assignment()?;

        // Check the left side of the assignment.
        // If it's not a variable return an error.
        match left {
            Expression::Variable(identifier) => Ok(Expression::Assignment {
                identifier,
                expression: Box::new(right),
            }),
            _ => Err(ParserError {
                message: String::from("Invalid assignment target"),
                token: equal,
            }),
        }
    }

    // Parse the next three tokens and try to
    // identify an equality.
    //
    // equality -> comparison ( ( "!=" | "==" ) comparison )*
    fn equality(&mut self) -> ParserResult<Expression> {
        self.binary(
            &[TokenType::BangEqual, TokenType::EqualEqual],
            Self::comparison,
        )
    }

    // Parse the next three tokens and try to
    // identify a comparison.
    //
    // comparison -> term ( ( ">" | ">=" | "<" | "<=" ) term )*
    fn comparison(&mut self) -> ParserResult<Expression> {
        self.binary(
            &[
                TokenType::Less,
                TokenType::LessEqual,
                TokenType::Greater,
                TokenType::GreaterEqual,
            ],
            Self::term,
        )
    }

    // Parse the next three tokens and try to
    // identify an addition or a subtraction.
    //
    // term -> factor ( ( "+" | "-" ) factor )*
    fn term(&mut self) -> ParserResult<Expression> {
        self.binary(&[TokenType::Plus, TokenType::Minus], Self::factor)
    }

    // Parse the next three tokens and try to
    // identify a multiplication or a division.
    //
    // factor -> unary ( ( "/" | "*" ) unary )*
    fn factor(&mut self) -> ParserResult<Expression> {
        self.binary(&[TokenType::Slash, TokenType::Star], Self::unary)
    }

    // Parse the next two tokens and try to
    // identify a unary operation.
    //
    // unary -> ( "!" | "-" ) unary | primary
    fn unary(&mut self) -> ParserResult<Expression> {
        if let Some(t) = self.match_current(&[TokenType::Bang, TokenType::Minus]) {
            return Ok(Expression::Unary {
                operator: t.clone(),
                right: Box::new(self.unary()?),
            });
        }

        self.primary()
    }

    // Parse the current token and try to
    // identify a primary element.
    //
    // primary -> NUMBER | STRING | "true" | "false" | "nil" | "(" expression ")" | IDENTIFIER
    fn primary(&mut self) -> ParserResult<Expression> {
        // Check if we are dealing with a group.
        // A group is closed by a specific token
        // (RParen), which needs to be matched
        // after the expression is parsed.
        if self.match_current(&[TokenType::LParen]).is_some() {
            // Parse the expression between brackets.
            let p = self.expression()?;

            // Enforce the presence of a
            // closing round bracket `)`.
            self.expect(&TokenType::RParen, "Missing closing round bracket ')'")?;

            return Ok(Expression::Group(Box::new(p)));
        }

        // Get the current token.
        let c: &Token = self.current_token();

        // Check the type of the current token.
        let result = match (&c.ttype, &c.literal) {
            (TokenType::Number, TokenLiteral::Number(n)) => {
                Expression::Literal(Literal::Number(*n))
            }
            (TokenType::Reserved(s), _) => match s {
                Keyword::True => Expression::Literal(Literal::Boolean(true)),
                Keyword::False => Expression::Literal(Literal::Boolean(false)),
                Keyword::Nil => Expression::Literal(Literal::Nil),
                _ => {
                    return Err(ParserError {
                        message: String::from("Invalid primary token"),
                        token: c.clone(),
                    })
                }
            },
            (TokenType::String, TokenLiteral::String(s)) => {
                Expression::Literal(Literal::String(s.to_string()))
            }
            (TokenType::Identifier, _) => Expression::Variable(c.clone()),
            _ => {
                return Err(ParserError {
                    message: String::from("Invalid primary token"),
                    token: c.clone(),
                });
            }
        };

        // If we reach this point, the token we
        // found was valid. Advance the index
        // consuming the current token.
        self.consume();

        // Return the token as a Result.
        Ok(result)
    }
}
